from decimal import Decimal

import pytest

from pricing import LineItem
from pricing.bulk_discount import (
    BULK_DISCOUNT_PERCENT,
    BULK_QUANTITY_THRESHOLD,
    calculate_bulk_discount,
    qualifies_for_bulk_discount,
)


class TestBulkDiscountConstants:
    """Test the module-level constants."""

    def test_bulk_quantity_threshold_is_10(self):
        """Req 1.1, 1.2, 1.3"""
        assert BULK_QUANTITY_THRESHOLD == 10

    def test_bulk_discount_percent_is_5_percent(self):
        """Req 1.1, 1.2"""
        assert BULK_DISCOUNT_PERCENT == Decimal("5")


class TestQualifiesForBulkDiscount:
    """Tests for the qualifies_for_bulk_discount function."""

    @pytest.mark.l4("C-8764baca", "C-e4015f6b", "C-4284227d")
    @pytest.mark.parametrize("qty,expected", [(9, False), (10, True), (11, True)])
    def test_quantity_threshold_boundary(self, qty: int, expected: bool):
        """Test quantities at and around the threshold."""
        item = LineItem("item", Decimal("10.00"), qty)
        assert qualifies_for_bulk_discount(item) is expected

    def test_non_qualifying_item_with_quantity_one(self):
        """Req 1.3"""
        item = LineItem("item", Decimal("100.00"), 1)
        assert qualifies_for_bulk_discount(item) is False

    def test_qualifying_item_with_high_quantity(self):
        """Req 1.2"""
        item = LineItem("item", Decimal("1.00"), 100)
        assert qualifies_for_bulk_discount(item) is True


