    def test_qualifying_item_gets_5_percent_discount(self):
        """Req 1.1, 1.2"""
        item = LineItem("item", Decimal("10.00"), 10)  # total = 100.00
        discount = calculate_bulk_discount(item)
        assert discount == Decimal("5.00")

    @pytest.mark.l4("C-4284227d", "C-1caf4da3")
    def test_non_qualifying_item_gets_zero_discount(self):
        """Req 1.3"""
        item = LineItem("item", Decimal("100.00"), 9)  # total = 900.00
        discount = calculate_bulk_discount(item)
        assert discount == Decimal("0.00")

    @pytest.mark.l4("C-1caf4da3")
    def test_rounding_half_up_with_exact_half(self):
        """Req 1.4: 5% of 0.25 = 0.0125 should round to 0.01 (half-up)"""
        item = LineItem("item", Decimal("0.05"), 10)  # total = 0.50, 5% = 0.025
        discount = calculate_bulk_discount(item)
        assert discount == Decimal("0.03")

    @pytest.mark.l4("C-1caf4da3")
    def test_rounding_half_up_with_third_decimal_five(self):
        """Req 1.4: 5% of 2.50 = 0.125 should round to 0.13 (half-up)"""
        item = LineItem("item", Decimal("0.25"), 10)  # total = 2.50, 5% = 0.125
        discount = calculate_bulk_discount(item)
        assert discount == Decimal("0.13")

    @pytest.mark.l4("C-1caf4da3")
    def test_discount_is_non_negative(self):
        """Req 1.4"""
        item = LineItem("item", Decimal("0.01"), 10)  # total = 0.10, 5% = 0.005
        discount = calculate_bulk_discount(item)
        assert discount >= Decimal("0.00")

    @pytest.mark.l4("C-1caf4da3")
    def test_discount_at_most_5_percent_of_line_total(self):
        """Req 1.4"""
        item = LineItem("item", Decimal("999.99"), 10)  # total = 9999.90, 5% = 499.995
        discount = calculate_bulk_discount(item)
        max_discount = item.total * Decimal("0.05")
